perl -0e '\''
  use strict;
  use warnings;

  my $path = shift @ARGV;
  open my $fh, q{<}, $path or die "open $path: $!\n";
  local $/;
  my $content = <$fh>;
  close $fh or die "close $path: $!\n";

  my $from = q{The generated GRUB `MOK Enrollment` entry documents the existing `/var/lib/shim-signed/secure-boot/MOK.der` certificate, searches the ESP, and chainloads the architecture-specific MokManager binary under `EFI/debian` (`mmx64.efi` on `amd64`, `mmaa64.efi` on `arm64`), so selecting it starts MokManager against the generated certificate.};
  my $to = q{The generated GRUB `MOK Enrollment` entry documents the existing `/var/lib/shim-signed/secure-boot/MOK.der` certificate and directly chainloads the architecture-specific MokManager binary beside the firmware-loaded GRUB image under `EFI/debian` (`mmx64.efi` on `amd64`, `mmaa64.efi` on `arm64`), so selecting it starts MokManager against the generated certificate without an ESP UUID or file search.};
  my $count = ($content =~ s/\Q$from\E/$to/g);
  die "expected exactly one README MOK description, found $count\n" unless $count == 1;
  print $content;
'\'' -- README.md > "$tmp"
cmp -s -- README.md "$tmp" && {
  printf "%s\\n" "README MOK documentation was already current" >&2
  exit 1
}
mv -- "$tmp" README.md
trap - EXIT HUP INT TERM'","workdir":"/home/mcramer/Workspace/debian-preseed-di-new","yield_time_ms":10000,"max_output_tokens":10000}

