     1	#!/bin/sh
     2	set -eu
     3	
     4	effective_ctype=${LC_ALL:-${LC_CTYPE:-${LANG:-}}}
     5	case "$effective_ctype" in
     6	  ''|C|POSIX)
     7	    LANG=C.UTF-8
     8	    LC_ALL=C.UTF-8
