    12	
    13	if [ -r /etc/default/labwc-desktop ]; then
    14	  # shellcheck disable=SC1091
    15	  . /etc/default/labwc-desktop
    16	fi
    17	
    18	# Accept xterm-style `-e` for callers, but normalize it before we reach Kitty.
    19	xterm_execute_mode=0
    20	case "${1:-}" in
    21	  -e|--execute)
    22	    xterm_execute_mode=1
    23	    exec_flag=$1
    24	    shift
    25	    [ "$#" -gt 0 ] || {
    26	      printf 'fatal: labwc-terminal requires a command after %s\n' "$exec_flag" >&2
    27	      exit 1
    28	    }
    29	    ;;
    30	esac
    31	
    32	seen_terminals=' '
    33	for terminal_cmd in "${LABWC_TERMINAL_PRIMARY:-foot}" "${LABWC_TERMINAL_FALLBACK:-kitty}" foot kitty x-terminal-emulator; do
    34	  [ -n "$terminal_cmd" ] || continue
    35	  case "$seen_terminals" in
    36	    *" $terminal_cmd "*) continue ;;
    37	  esac
    38	  seen_terminals="${seen_terminals}${terminal_cmd} "
    39	  if command -v "$terminal_cmd" >/dev/null 2>&1; then
    40	    case "$terminal_cmd" in
    41	      kitty)
    42	        exec "$terminal_cmd" "$@"
    43	        ;;
    44	    esac
    45	    if [ "$xterm_execute_mode" -eq 1 ]; then
    46	      exec "$terminal_cmd" -e "$@"
    47	    fi
    48	    exec "$terminal_cmd" "$@"
    49	  fi
    50	done
    51	
    52	printf 'fatal: no supported terminal is installed\n' >&2
    53	exit 1

