    return $self->command->run_quiet(
        10,
        $systemctl,
        '--user',
        'is-active',
        '--quiet',
        SERVER_UNIT,
    ) == 0 ? 1 : 0;
}

sub _run_service_command {
    my ($self, $operation) = @_;
    $operation =~ /\A(?:start|restart|stop)\z/
