--- result 1 ---
-- audit route --
     1	# Tail auditd's authoritative ENRICHED file directly and route the records to a
     2	# dedicated correlation log. imfile injects the records inside rsyslog instead
     3	# of sending them through /dev/log, so systemd-journald never receives the
     4	# duplicated audit stream. Early kernel and audit daemon status records remain
     5	# covered by the socket and kernel inputs.
     6	
     7	# Polling avoids rsyslog's inotify watch-descriptor churn when auditd rotates or
     8	# recreates its authoritative log.
     9	module(load="imfile" mode="polling" PollingInterval="1")
    10	
    11	input(
    12	  type="imfile"
    13	  File="/var/log/audit/audit.log"
    14	  Tag="auditd-file:"
    15	  Facility="local0"
    16	  Severity="info"
    17	  PersistStateInterval="100"
    18	  deleteStateOnFileDelete="on"
    19	  deleteStateOnFileMove="on"
    20	)
    21	
    22	if (
    23	  $programname == "auditd-file" or
    24	  $programname == "audit" or
    25	  $programname == "auditd" or
    26	  (
    27	    $syslogfacility-text == "kern" and (
    28	      $msg contains "audit:" or
    29	      $msg contains "audit("
    30	    )
    31	  )
    32	) then {
    33	  set $.managed_security_routed = "on";
    34	  action(
    35	    name="managed_kernel_audit_log"
    36	    type="omfile"
    37	    file="/var/log/managed/audit/kernel-audit.log"
    38	    fileOwner="root"
    39	    fileGroup="adm"
    40	    fileCreateMode="0640"
    41	    dirOwner="root"
    42	    dirGroup="adm"
    43	    dirCreateMode="0750"
    44	    createDirs="on"
    45	    template="RSYSLOG_TraditionalFileFormat"
    46	  )
    47	}
-- audit rule headers --
## Managed by installer late_command.
## Standard profile: native-ABI, targeted integrity coverage for desktops.
## Keep this profile low-noise: no old-style -w watches, no catch-all execve,
## no broad /etc or network syscall capture.
## auditctl requires syscall selectors on arch-qualified perm/path/dir rules.

-D
-b 8192
--backlog_wait_time 60000
## auditctl/augenrules status prints this as "failure 1"; it is the kernel
## audit failure mode (printk), not a rule load failure.
-f 1

## Ignore kernel pseudo-filesystems before any filesystem-scoped checks.
-a never,filesystem -F fstype=debugfs
-a never,filesystem -F fstype=tracefs

## AppArmor policy changes; AppArmor denials are emitted by the kernel LSM into audit.
## Managed by installer late_command.
## Enhanced profile: broader native-ABI integrity coverage without old-style
## -w watches, catch-all execve, networking, or global file-open syscall rules.
## auditctl requires syscall selectors on arch-qualified perm/path/dir rules.

-D
-b 16384
--backlog_wait_time 120000
## auditctl/augenrules status prints this as "failure 1"; it is the kernel
## audit failure mode (printk), not a rule load failure.
-f 1

## Ignore kernel pseudo-filesystems before any filesystem-scoped checks.
-a never,filesystem -F fstype=debugfs
-a never,filesystem -F fstype=tracefs

## AppArmor policy changes; AppArmor denials are emitted by the kernel LSM into audit.
-a always,exit -F arch=b64 -S openat -S truncate -S ftruncate -S chmod -S fchmod -S fchmodat -S chown -S fchown -S fchownat -S lchown -S rename -S renameat -S renameat2 -S unlink -S unlinkat -S setxattr -S lsetxattr -S fsetxattr -S removexattr -S lremovexattr -S fremovexattr -F dir=/etc/apparmor.d -F perm=wa -F key=apparmor-policy

